#include "nsmp.hpp"
#include <fstream>
namespace lp::nsmp {
Bytes readFile(const std::filesystem::path& path){auto size=std::filesystem::file_size(path);if(size>256u*1024u*1024u)throw std::runtime_error("Nord: limite de 256 MiB por arquivo");Bytes b(static_cast<std::size_t>(size));std::ifstream in(path,std::ios::binary);if(!in.read(reinterpret_cast<char*>(b.data()),b.size()))throw std::runtime_error("Nord: falha na leitura");return b;}
CbinHeader readCbin(const Bytes& b){View v(b);v.require(0,24);if(std::string(b.begin(),b.begin()+4)!="CBIN")throw std::runtime_error("Nord: assinatura CBIN ausente");CbinHeader h;h.formatType=v.le(4,4);if(h.formatType>1)throw std::runtime_error("Nord: formatType >=2 não suportado");h.tag.assign(b.begin()+8,b.begin()+12);while(!h.tag.empty()&&(h.tag.back()==0||h.tag.back()==' '))h.tag.pop_back();h.bank=static_cast<std::uint16_t>(v.le(12,2));h.slot=static_cast<std::uint16_t>(v.le(14,2));h.category=v.le(16,4);h.version=v.le(20,4);h.recordOffset=h.formatType==1?44:24;auto trailer=h.formatType==0?2u:0u;v.require(h.recordOffset,trailer);h.recordLength=b.size()-h.recordOffset-trailer;if(h.formatType==1)h.crc32=v.le(24,4);return h;}
Identity identifyNsmp(const Bytes& b){Identity id;id.header=readCbin(b);if(id.header.tag!="nsmp")throw std::runtime_error("CBIN não é uma amostra Nord: tag "+id.header.tag);View v(b);id.body=static_cast<std::size_t>(id.header.recordOffset);id.end=b.size()-(id.header.formatType==0?2:0);v.require(id.body,3);id.legacy=v.be(id.body,3)==0x4e5753;id.headerSize=id.legacy?9:12;if(!id.legacy&&(id.body+4>id.end||v.be(id.body,4)!=0x4e534d50))throw std::runtime_error("Nord: raiz NWS/NSMP ausente");auto version=id.header.version&0xffff;id.codec=version==0xffff||version==8?1:static_cast<int>(version/100);if((id.legacy&&(id.codec<1||id.codec>2))||(!id.legacy&&id.codec!=3&&id.codec!=4))throw std::runtime_error("Nord: geração não suportada");return id;}
}
